import Int64 = require( '@stdlib/number/int64/ctor' );
import mul = require( './index' );


// TESTS //

// The function returns a 64-bit signed integer...
{
	const a = new Int64( 5 );

	mul( a, a ); // $ExpectType Int64
}

// The compiler throws an error if the function is provided a first argument which is not a 64-bit signed integer...
{
	const a = new Int64( 5 );

	mul( true, a ); // $ExpectError
	mul( false, a ); // $ExpectError
	mul( null, a ); // $ExpectError
	mul( undefined, a ); // $ExpectError
	mul( '5', a ); // $ExpectError
	mul( [], a ); // $ExpectError
	mul( {}, a ); // $ExpectError
	mul( ( x: number ): number => x, a ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is not a 64-bit signed integer...
{
	const a = new Int64( 5 );

	mul( a, true ); // $ExpectError
	mul( a, false ); // $ExpectError
	mul( a, null ); // $ExpectError
	mul( a, undefined ); // $ExpectError
	mul( a, '5' ); // $ExpectError
	mul( a, [] ); // $ExpectError
	mul( a, {} ); // $ExpectError
	mul( a, ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const a = new Int64( 5 );

	mul(); // $ExpectError
	mul( a ); // $ExpectError
	mul( a, a, a ); // $ExpectError
}

// Attached to the main export is an `assign` method which returns an array-like object containing numbers...
{
	const out = [ 0.0, 0.0 ];

	mul.assign( 1, 2, 3, 4, out, 1, 0 ); // $ExpectType number[]
	mul.assign( 1, 2, 3, 4, new Float64Array( 2 ), 1, 0 ); // $ExpectType Float64Array
	mul.assign( 1, 2, 3, 4, new Uint32Array( 2 ), 1, 0 ); // $ExpectType Uint32Array
}

// Attached to the main export is a `strided` method which returns an array-like object containing numbers...
{
	const a = [ 1.0, 2.0 ];
	const b = [ 3.0, 4.0 ];
	const out = [ 0.0, 0.0 ];

	mul.strided( a, 1, 0, b, 1, 0, out, 1, 0 ); // $ExpectType number[]
	mul.strided( new Float64Array( a ), 1, 0, new Float64Array( b ), 1, 0, new Float64Array( 2 ), 1, 0 ); // $ExpectType Float64Array
	mul.strided( new Uint32Array( a ), 1, 0, new Uint32Array( b ), 1, 0, new Uint32Array( 2 ), 1, 0 ); // $ExpectType Uint32Array
}
